def _tfidf_vector(tokens: list[str], corpus: list[list[str]]) -> dict[str, float]:
    tf = _tf(tokens)
    return {t: score * _idf(t, corpus) for t, score in tf.items()}

def _idf(term: str, corpus: list[list[str]]) -> float:
